    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '111: A child with a "splenectomy" requires which extra vaccine before or after the procedure?', '["MMR", "PPSV23 (Pneumovax)", "RV", "HepA"]', 1, 'Asplenic patients need extra protection against encapsulated bacteria like S. pneumoniae. (Nelson)'),
    (v_topic_id, '112: Which of the following vaccines is NOT given as a series in the first year of life?', '["HepB", "PCV13", "HPV", "RV"]', 2, 'HPV is an adolescent vaccine (age 9-12). (Harriet Lane)'),
    (v_topic_id, '113: A 7-year-old child needs a tetanus-containing vaccine after a puncture wound. Their last DTaP was at age 4. What is the appropriate vaccine?', '["DTaP", "Tdap", "Td", "TT (Tetanus Toxoid only)"]', 1, 'Tdap is the preferred vaccine for adolescents and for tetanus prophylaxis in children aged 7+. (Nelson)'),
    (v_topic_id, '114: Which of the following is a symptom of "measles" that the MMR vaccine prevents?', '["Cough, Coryza, Conjunctivitis (3 Cs)", "Vomiting", "Diarrhea", "Joint pain"]', 0, 'The classic 3 Cs + Koplik spots precede the measles rash. (Case Files)'),
    (v_topic_id, '115: Which vaccine protects against a virus that can cause "hemorrhagic cystitis" or severe respiratory disease, though it is only given to military recruits?', '["Adenovirus vaccine", "Influenza", "HepB", "IPV"]', 0, 'The Adenovirus vaccine is not routine for civilians but is mentioned in some pediatrics texts. (Nelson)'),
    (v_topic_id, '116: At what age should "blood pressure" measurement begin at every well-child visit?', '["Birth", "1 year", "3 years", "5 years"]', 2, 'Routine BP screening starts at age 3. (Harriet Lane)'),
    (v_topic_id, '117: Which of the following is the most common cause of "failure to thrive" (FTT)?', '["Celiac disease", "Cystic fibrosis", "Inadequate caloric intake (Psychosocial)", "Growth hormone deficiency"]', 2, 'Environmental and psychosocial factors account for most FTT cases. (Nelson)'),
    (v_topic_id, '118: A child has a BMI at the 97th percentile. They are classified as:', '["Normal", "Overweight", "Obese", "Severely obese"]', 2, 'BMI >= 95th percentile is obese. (CDC)'),
    (v_topic_id, '119: What is the "Head Circumference" growth rate in the first year of life?', '["12 cm total", "6 cm total", "20 cm total", "1 cm total"]', 0, 'Head circumference grows ~12 cm in the first year. (Nelson)'),
    (v_topic_id, '120: At what age does the "Moro reflex" typically disappear?', '["1 month", "4 months", "9 months", "12 months"]', 1, 'The Moro reflex should be gone by 3-4 months. (Case Files)'),
    (v_topic_id, '121: Which vaccine is associated with a lower risk of "Infant Botulism"?', '["MMR", "None", "Hib", "RV"]', 1, 'There is no vaccine for botulism; it is prevented by avoiding honey in infants <1 year. (Nelson)'),
    (v_topic_id, '122: Which of the following is the most common nutritional deficiency in children worldwide?', '["Vitamin D", "Iron", "Vitamin C", "Vitamin A"]', 1, 'Iron deficiency is highly prevalent, especially in toddlers and adolescent females. (Harriet Lane)'),
    (v_topic_id, '123: At what age is "crawling" typically achieved?', '["4 months", "6 months", "9 months", "12 months"]', 2, 'Crawling is a 9-month milestone. (Nelson)'),
    (v_topic_id, '124: A 12-month-old is not "babbling." Is this a concern?', '["No", "Yes, a red flag for hearing or autism", "Wait until 18 months", "Only if they can''t walk"]', 1, 'Lack of babbling or gestures by 12 months is a developmental concern. (Case Files)'),
    (v_topic_id, '125: Which vaccine is given to prevent "congenital rubella syndrome"?', '["MMR", "DTaP", "Varicella", "PCV13"]', 0, 'Rubella (the last R in MMR) is devastating to the fetus if a mother is infected during pregnancy. (Nelson)'),
    (v_topic_id, '126: What is the most common complication of varicella (chickenpox) in a healthy child?', '["Pneumonia", "Encephalitis", "Secondary bacterial skin infection (Staph/Strep)", "Shingles"]', 2, 'Scratching itchy vesicles leads to impetigo or cellulitis. (Nelson)'),
    (v_topic_id, '127: Which vaccine is associated with preventing "acute epiglottitis"?', '["Hib", "PCV13", "MMR", "IPV"]', 0, 'H. influenzae type b was the dominant cause before vaccination. (Case Files)'),
    (v_topic_id, '128: Which of the following is a "live" vaccine?', '["HepB", "IPV", "Varicella", "PCV13"]', 2, 'Varicella is a live-attenuated virus. (Harriet Lane)'),
    (v_topic_id, '129: Can a child with a "well-controlled" HIV infection receive the MMR vaccine?', '["No, never", "Yes, if CD4 count is >15% or >200-500 depending on age", "Only the inactivated version", "Only after age 18"]', 1, 'MMR and Varicella can be given to HIV+ children who are NOT severely immunocompromised. (Nelson)'),
    (v_topic_id, '130: Which vaccine contains "mercury" (Thimerosal) in single-dose vials in the US?', '["None", "MMR", "Varicella", "DTaP"]', 0, 'Single-dose vials of routine childhood vaccines in the US have been thimerosal-free since 2001. (CDC)'),
    (v_topic_id, '131: At what age should a child "cruise" (walk while holding onto furniture)?', '["6 months", "9 months", "12 months", "15 months"]', 1, 'Cruising is a classic 9-month milestone. (Nelson)'),
    (v_topic_id, '132: What is the "Rule of 3s" for infant colic?', '["3 hours/day, 3 days/week, for 3 weeks", "3 months old, 3 cries, 3 feeds", "3 lbs weight loss", "None"]', 0, 'Wessel criteria for colic diagnosis. (Nelson)'),
    (v_topic_id, '133: A 4-year-old child should be able to stack how many blocks?', '["2", "6", "10", "Unlimited"]', 2, 'Stacking 10 blocks (a tower) is a 3-4 year milestone. (Harriet Lane)'),
    (v_topic_id, '134: At what age should a child be able to "hop on one foot"?', '["2 years", "3 years", "4 years", "5 years"]', 2, 'Hopping on one foot is a 4-year-old milestone. (Nelson)'),
    (v_topic_id, '135: What is the "Rule of 4s" for speech?', '["100% intelligible to strangers by age 4", "4 words at 1 year", "4 sentences at 4 years", "None"]', 0, 'Speech intelligibility: 2y (50%), 3y (75%), 4y (100%). (Case Files)'),
    (v_topic_id, '136: Which vaccine protects against "lockjaw"?', '["Pertussis", "Diphtheria", "Tetanus", "Polio"]', 2, 'Tetanus causes trismus (lockjaw). (Nelson)'),
    (v_topic_id, '137: A 2-month-old infant has a "hemangioma." Is this a reason to delay vaccines?', '["Yes", "No", "Only if it is bleeding", "Only if it is on the thigh"]', 1, 'Hemangiomas are not a contraindication to vaccination. (Nelson)'),
    (v_topic_id, '138: Which of the following is the most common cause of "acute gastroenteritis" in infants before the vaccine era?', '["E. coli", "Salmonella", "Rotavirus", "Adenovirus"]', 2, 'Rotavirus was a major cause of pediatric hospitalization for dehydration. (Case Files)'),
    (v_topic_id, '139: The second dose of the MMR vaccine is usually given at what age?', '["15 months", "2 years", "4-6 years", "11-12 years"]', 2, 'The 4-6 year visit is for the second dose. (CDC)'),
    (v_topic_id, '140: At what age should a child first double their "birth weight"?', '["2 months", "4-5 months", "12 months", "24 months"]', 1, 'Birth weight doubles by 5 months and triples by 1 year. (Harriet Lane)'),
    (v_topic_id, '141: At what age should a child first double their "birth length"?', '["1 year", "2 years", "4 years", "6 years"]', 2, 'Length doubles by age 4. (Nelson)'),
    (v_topic_id, '142: Which vaccine is associated with preventing "liver cancer" (Hepatocellular carcinoma)?', '["HepA", "HepB", "MMR", "HPV"]', 1, 'Chronic Hepatitis B infection is a leading cause of liver cancer. (Nelson)'),
    (v_topic_id, '143: A child is born to an HBsAg-negative mother but weighs <2000g. When do you give the first HepB dose?', '["At birth", "At 30 days of age or at discharge", "At 6 months", "Never"]', 1, 'For low-birth-weight infants of negative mothers, the vaccine is delayed to 1 month. (CDC)'),
    (v_topic_id, '144: A 12-month-old child has an allergy to "peanuts." Can they receive the MMR vaccine?', '["No", "Yes", "Only if they have an EpiPen", "Only after skin testing"]', 1, 'Peanut allergy is not a contraindication to any routine vaccine. (Nelson)'),
    (v_topic_id, '145: Which vaccine is given to prevent "parotitis" and "orchitis"?', '["MMR", "DTaP", "HPV", "HepB"]', 0, 'Mumps (in MMR) causes swelling of the parotid glands and can cause orchitis. (Case Files)'),
    (v_topic_id, '146: What is the most common side effect of the "DTaP" vaccine?', '["High fever", "Local redness, swelling, and pain at the injection site", "Seizures", "Encephalopathy"]', 1, 'Local reactions are common and usually mild. (Harriet Lane)'),
    (v_topic_id, '147: Which vaccine is associated with a risk of "transverse myelitis" or "GBS" although extremely rare?', '["Influenza", "HepB", "MMR", "None specifically linked strongly"]', 0, 'GBS has a historical link with influenza vaccines, though the risk is ~1 in a million. (Nelson)'),
    (v_topic_id, '148: At what age is the "anterior fontanelle" typically closed?', '["2 months", "6 months", "12-18 months", "3 years"]', 2, 'The posterior fontanelle closes at 2 months; the anterior at 12-18 months. (Harriet Lane)'),
    (v_topic_id, '149: Which of the following is a "red flag" for a 2-month-old?', '["Not rolling", "Not sitting", "Not smiling socially", "Not babbling"]', 2, 'Social smile should be present by 2 months. (Nelson)'),
    (v_topic_id, '150: At what age should a child "roll from front to back"?', '["2 months", "4 months", "6 months", "9 months"]', 1, 'Rolling over typically starts at 4 months. (Case Files)'),
    (v_topic_id, '151: Which vaccine is associated with the prevention of "congenital deafness" and "cataracts" if given to the mother before pregnancy?', '["MMR (Rubella component)", "HepB", "IPV", "PCV13"]', 0, 'Rubella causes the classic triad of deafness, cataracts, and heart defects in the fetus. (Nelson)'),
    (v_topic_id, '152: Which vaccine is given to prevent a "barking cough" (Croup) caused by a specific virus?', '["None (Croup is mostly Parainfluenza)", "Influenza (if causing croup)", "DTaP", "MMR"]', 0, 'There is no vaccine for parainfluenza, the most common cause of croup. (Nelson)'),
    (v_topic_id, '153: At what age can a child safely start "cow''s milk"?', '["6 months", "9 months", "12 months", "24 months"]', 2, 'Whole cow''s milk is recommended starting at 12 months (not before). (Harriet Lane)'),
    (v_topic_id, '154: Why is cow''s milk avoided before 12 months?', '["It is too expensive", "It can cause occult GI bleeding and iron-deficiency anemia", "It causes obesity", "It has too much Vitamin D"]', 1, 'Cow''s milk has low iron and can cause microscopic bleeding in the infant gut. (Case Files)'),
    (v_topic_id, '155: What is the recommended maximum intake of cow''s milk per day for a toddler?', '["16-24 oz", "32 oz", "Unlimited", "8 oz"]', 0, 'Excess milk intake is a major risk factor for iron deficiency in toddlers. (Nelson)'),
    (v_topic_id, '156: At what age should a child "sit with support"?', '["2 months", "4 months", "6 months", "9 months"]', 2, '6 months is the milestone for sitting (often tripod sitting). (Harriet Lane)'),
    (v_topic_id, '157: Which of the following is a "live" vaccine administered orally?', '["IPV", "RV (Rotavirus)", "Hib", "PCV13"]', 1, 'The Rotavirus vaccine is a live-attenuated oral vaccine. (Nelson)'),
    (v_topic_id, '158: What is the minimum interval between the 1st and 2nd dose of MMR?', '["1 week", "2 weeks", "4 weeks (28 days)", "6 months"]', 2, 'Minimum interval for catch-up is 4 weeks. (CDC)'),
    (v_topic_id, '159: Which of the following is a contraindication for the "LAIV" (Live Attenuated Influenza Vaccine)?', '["Age < 2 years", "Pregnancy", "Aspirin therapy in children", "All of the above"]', 3, 'LAIV has more contraindications than the inactivated vaccine. (Nelson)'),
    (v_topic_id, '160: At what age should a child start being screened for "scoliosis"?', '["2 years", "5 years", "10 years (or onset of puberty)", "Birth"]', 2, 'Scoliosis screening typically starts in late childhood/early adolescence. (Harriet Lane)'),
    (v_topic_id, '161: Which vaccine is associated with preventing "whooping cough" (Pertussis)?', '["Hib", "DTaP", "PCV13", "MMR"]', 1, 'DTaP is the vaccine for pertussis in young children. (Case Files)'),
    (v_topic_id, '162: At what age should a child be able to "jump with two feet"?', '["18 months", "2 years", "3 years", "4 years"]', 1, 'Jumping in place is a 2-year-old milestone. (Nelson)'),
    (v_topic_id, '163: A 4-year-old child can draw what shape?', '["Circle", "Cross", "Square", "Diamond"]', 1, 'Circle (3y), Cross (4y), Square (4.5y), Triangle (5y). (Harriet Lane)'),
    (v_topic_id, '164: Which vaccine is associated with preventing "invasive disease" like sepsis and pneumonia in children with Sickle Cell Disease?', '["PCV13 and PPSV23", "HepB", "IPV", "RV"]', 0, 'Pneumococcal disease is a major cause of mortality in sickle cell patients. (Nelson)'),
    (v_topic_id, '165: At what age should a child have "20/20" vision?', '["Birth", "2 years", "3-5 years", "10 years"]', 2, 'Vision matures in the preschool years. (Case Files)'),
    (v_topic_id, '166: Which of the following is the most common cause of "acute otitis media"?', '["S. pneumoniae", "H. influenzae", "M. catarrhalis", "All are common"]', 3, 'These three bacteria are the primary causes of ear infections. (Nelson)'),
    (v_topic_id, '167: Which vaccine has reduced the incidence of "acute otitis media" caused by specific serotypes?', '["PCV13", "MMR", "HepB", "IPV"]', 0, 'Pneumococcal conjugate vaccine has reduced ear infections. (Harriet Lane)'),
    (v_topic_id, '168: At what age can a child "climb stairs with alternating feet"?', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Alternating feet going up is a 3-year-old milestone. (Nelson)'),
    (v_topic_id, '169: Which vaccine is given to prevent "German Measles"?', '["MMR", "DTaP", "Varicella", "PCV13"]', 0, 'Rubella is the German Measles component. (Case Files)'),
    (v_topic_id, '170: What is the "Rule of 2s" for childhood dental health?', '["Brush 2 times a day, see dentist 2 times a year", "2 minutes brushing", "2 teeth", "None"]', 0, 'Basic preventive dental advice. (Nelson)'),
    (v_topic_id, '171: At what age should a child start using "fluoride-containing toothpaste"?', '["Birth (as soon as first tooth erupts)", "2 years", "3 years", "5 years"]', 0, 'The AAP now recommends a "smear" of fluoride toothpaste from the first tooth. (AAP/Nelson)'),
    (v_topic_id, '172: What is the "smear" amount of toothpaste?', '["The size of a pea", "The size of a grain of rice", "A big dollop", "None"]', 1, 'A rice-sized smear for children <3; a pea-sized amount for children >3. (Nelson)'),
    (v_topic_id, '173: Which of the following is a "red flag" for a 12-month-old?', '["Not walking", "Not saying 5 words", "Not using a ''pincer grasp''", "Not crawling"]', 2, 'Pincer grasp (picking up small items with thumb/finger) is an 8-10 month skill. (Case Files)'),
    (v_topic_id, '174: At what age should a child "point to things to show them to others"?', '["6 months", "9 months", "12 months", "18 months"]', 2, 'Pointing (proto-declarative) is a key social milestone at 12 months. (Nelson)'),
    (v_topic_id, '175: Which vaccine is given as a "booster" at age 16?', '["Tdap", "MenACWY", "MMR", "Varicella"]', 1, 'Meningococcal booster is vital for college-age protection. (CDC)'),
    (v_topic_id, '176: A 2-year-old child should be able to follow how many steps in a command?', '["1", "2", "3", "4"]', 1, '2 years = 2-step commands. (Harriet Lane)'),
    (v_topic_id, '177: Which of the following is a sign of "ready" for solid foods?', '["Being 2 months old", "Sitting with support and disappearance of the extrusion reflex", "Having 4 teeth", "Weight > 10 lbs"]', 1, 'Usually around 4-6 months of age. (Nelson)'),
    (v_topic_id, '178: What is the first solid food typically introduced?', '["Meat", "Vegetables", "Iron-fortified cereal (rice or oatmeal)", "Fruit"]', 2, 'Single-grain iron-fortified cereals are the traditional first food. (Case Files)'),
    (v_topic_id, '179: Why is "honey" avoided before age 1?', '["It is too sweet", "Risk of infant botulism", "It causes tooth decay", "Allergies"]', 1, 'Clostridium botulinum spores can germinate in the infant gut. (Nelson)'),
    (v_topic_id, '180: Which vaccine is administered in the "anterolateral thigh" of an infant?', '["MMR", "HepB", "PCV13", "Both B and C"]', 3, 'HepB and PCV are IM vaccines given in the thigh. (Harriet Lane)'),
    (v_topic_id, '181: A child has a "stable" neurologic condition (e.g., CP). Is this a contraindication to DTaP?', '["Yes", "No", "Only if they have seizures", "Only if they are >1 year"]', 1, 'Stable conditions are NOT contraindications. (Nelson)'),
    (v_topic_id, '182: What is the recommended "water intake" for an infant <6 months?', '["None (except formula/breast milk)", "2 oz/day", "Unlimited", "4 oz/day"]', 0, 'Extra water is not needed and can lead to hyponatremia. (Case Files)'),
    (v_topic_id, '183: At what age should a child be screened for "autism"?', '["12 months", "18 and 24 months", "3 years", "5 years"]', 1, 'Specific M-CHAT screening at 18 and 24 months. (Nelson)'),
    (v_topic_id, '184: Which vaccine is associated with preventing "cervical, anal, and oropharyngeal cancer"?', '["MMR", "HepB", "HPV", "Varicella"]', 2, 'HPV vaccine prevents multiple types of cancer. (Nelson)'),
    (v_topic_id, '185: A 5-year-old child can "draw a person" with how many parts?', '["2", "3", "6", "10"]', 2, '3 parts at 4y; 6 parts at 5y. (Harriet Lane)'),
    (v_topic_id, '186: At what age should a child be able to "balance on one foot for 10 seconds"?', '["3 years", "4 years", "5 years", "6 years"]', 2, '5 years is the milestone for 10-second balance. (Nelson)'),
    (v_topic_id, '187: Which vaccine is associated with preventing "shingles" in adults?', '["Varicella vaccine in childhood", "Zoster vaccine in adults", "Both", "None"]', 2, 'The childhood vaccine prevents the primary infection. (Nelson)'),
    (v_topic_id, '188: A child has a "high fever" and a "seizure" 10 days after MMR. Is this likely related?', '["No", "Yes, MMR can cause fever/seizures at 7-12 days", "Only if it lasted 30 mins", "Only if they have a rash"]', 1, 'The timing matches the live-virus replication cycle. (Case Files)'),
    (v_topic_id, '189: At what age is a child "100% intelligible" to a stranger?', '["2 years", "3 years", "4 years", "5 years"]', 2, '4 years is the goal for 100% intelligibility. (Nelson)'),
    (v_topic_id, '190: Which vaccine contains "egg" protein and may be a concern for severe anaphylaxis (though usually safe)?', '["Influenza", "MMR", "Varicella", "HepB"]', 0, 'Influenza and Yellow Fever are grown in eggs. (Nelson)'),
    (v_topic_id, '191: At what age should a child "stack a tower of 3 blocks"?', '["12 months", "18 months", "24 months", "3 years"]', 1, '18 months = 3 blocks. (Harriet Lane)'),
    (v_topic_id, '192: A 2-year-old child should be able to stack how many blocks?', '["2", "4", "6", "8"]', 2, '2 years = 6 blocks. (Nelson)'),
    (v_topic_id, '193: Which vaccine is given to prevent "meningitis" caused by N. meningitidis?', '["PCV13", "Hib", "MenACWY", "MMR"]', 2, 'MenACWY is the Meningococcal vaccine. (Case Files)'),
    (v_topic_id, '194: At what age is the "first dose" of Hepatitis B vaccine usually given?', '["Birth", "2 months", "4 months", "6 months"]', 0, 'HepB is the birth vaccine. (CDC)'),
    (v_topic_id, '195: A child has a "bruise" after a vaccine. Management?', '["Call EMS", "Reassure parents and apply cool compress", "Give antibiotics", "Surgical drainage"]', 1, 'Minor local reactions are expected. (Nelson)'),
    (v_topic_id, '196: At what age should a child "scribble" spontaneously?', '["12 months", "18 months", "2 years", "3 years"]', 1, 'Scribbling is an 18-month milestone. (Harriet Lane)'),
    (v_topic_id, '197: Which vaccine is given to prevent "chickenpox"?', '["MMR", "Varicella", "IPV", "Hib"]', 1, 'Varicella-zoster virus causes chickenpox. (Case Files)'),
    (v_topic_id, '198: At what age should a child "stand alone"?', '["9 months", "12 months", "15 months", "18 months"]', 1, '12 months is the milestone for standing alone and starting to walk. (Nelson)'),
    (v_topic_id, '199: Which vaccine is given as a "subcutaneous" injection?', '["Varicella", "HepB", "PCV13", "DTaP"]', 0, 'Live vaccines like Varicella are SC. (Harriet Lane)'),
    (v_topic_id, '200: A child has a "high fever" and "drooling" (Epiglottitis). Which vaccine did they likely miss?', '["MMR", "Hib", "HepB", "IPV"]', 1, 'Hib prevents H. influenzae type b epiglottitis. (Case Files)'),
    (v_topic_id, '201: At what age should a child be "screened for lead"?', '["1 and 2 years", "5 years", "10 years", "Birth"]', 0, 'Lead screening at 1 and 2 years. (Nelson)'),
    (v_topic_id, '202: Which vaccine is given to prevent "tetanus"?', '["DTaP", "Tdap", "Td", "All of the above"]', 3, 'All contain the tetanus toxoid. (Harriet Lane)'),
    (v_topic_id, '203: At what age should a child "copy a circle"?', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Circle = 3 years. (Nelson)'),
    (v_topic_id, '204: Which vaccine is given to prevent "measles"?', '["MMR", "Varicella", "PCV13", "HepB"]', 0, 'Measles is the first M in MMR. (Case Files)'),
    (v_topic_id, '205: At what age should a child "run"?', '["12 months", "18 months", "24 months", "3 years"]', 1, 'Running is an 18-month milestone. (Harriet Lane)'),
    (v_topic_id, '206: Which vaccine is associated with preventing "pneumonia" caused by S. pneumoniae?', '["Hib", "PCV13", "MMR", "IPV"]', 1, 'PCV13 is the pneumococcal vaccine. (Nelson)'),
    (v_topic_id, '207: At what age should a child "climb onto a chair"?', '["12 months", "18 months", "24 months", "3 years"]', 1, '18-month milestone. (Nelson)'),
    (v_topic_id, '208: Which vaccine is given to prevent "mumps"?', '["MMR", "DTaP", "HPV", "HepB"]', 0, 'Mumps is in MMR. (Case Files)'),
    (v_topic_id, '209: At what age should a child "turn pages in a book"?', '["12 months", "18 months", "24 months", "3 years"]', 1, '18-month milestone. (Harriet Lane)'),
    (v_topic_id, '210: Which vaccine is given to prevent "rubella"?', '["MMR", "Varicella", "PCV13", "HepB"]', 0, 'Rubella is the R in MMR. (Case Files)'),
    (v_topic_id, '211: At what age should a child "use a spoon"?', '["12 months", "18 months", "24 months", "3 years"]', 1, '18-month milestone. (Nelson)'),
    (v_topic_id, '212: Which vaccine is given to prevent "polio"?', '["IPV", "PCV13", "MMR", "HepB"]', 0, 'IPV is the polio vaccine. (Harriet Lane)'),
    (v_topic_id, '213: At what age should a child "point to body parts"?', '["15 months", "18 months", "2 years", "3 years"]', 1, '18-month milestone. (Case Files)'),
    (v_topic_id, '214: Which vaccine is given to prevent "hepatitis A"?', '["HepA", "HepB", "MMR", "IPV"]', 0, 'HepA is the vaccine. (Nelson)'),
    (v_topic_id, '215: At what age should a child "take off some clothes"?', '["15 months", "18 months", "2 years", "3 years"]', 1, '18-month milestone. (Harriet Lane)'),
    (v_topic_id, '216: Which vaccine is given to prevent "rotavirus"?', '["RV", "Hib", "PCV13", "IPV"]', 0, 'RV is the vaccine. (Nelson)'),
    (v_topic_id, '217: At what age should a child "play with others (parallel play)"?', '["1 year", "2 years", "3 years", "4 years"]', 1, '2-year-old milestone. (Case Files)'),
    (v_topic_id, '218: Which vaccine is given to prevent "diphtheria"?', '["DTaP", "Tdap", "Td", "All of the above"]', 3, 'All contain diphtheria toxoid. (Harriet Lane)'),
    (v_topic_id, '219: At what age should a child "kick a ball"?', '["18 months", "2 years", "3 years", "4 years"]', 1, '2-year-old milestone. (Nelson)'),
    (v_topic_id, '220: Which vaccine is given to prevent "human papillomavirus"?', '["HPV", "HepB", "MMR", "Varicella"]', 0, 'HPV is the vaccine. (Case Files)');
